select
    DTQ.DTQ_FILORI,
    DTQ.DTQ_VIAGEM,
    DT6.DT6_DOC,
    DT6.DT6_SERIE,
    convert(date, DT6.DT6_DATEMI, 103) as DT6_DATEMI,
    DA8.DA8_DESC,
    DTQ.DTQ_KMVGE,

    (
        select convert(date, DTW010.DTW_DATREA, 103)
        from DTW010 (nolock)
        where 
                DTW010.D_E_L_E_T_ = ''
            and DTW010.DTW_FILORI = DTQ.DTQ_FILORI
            and DTW010.DTW_VIAGEM = DTQ.DTQ_VIAGEM
            and DTW010.DTW_ATIVID = '049'
    ) as DATAINI,
    (
        select convert(date, DTW010.DTW_DATREA, 103)
        from DTW010 (nolock)
        where 
                DTW010.D_E_L_E_T_ = ''
            and DTW010.DTW_FILORI = DTQ.DTQ_FILORI
            and DTW010.DTW_VIAGEM = DTQ.DTQ_VIAGEM
            and DTW010.DTW_ATIVID = '050'
    ) as DATAFIM,
    (
        select substring(DTW010.DTW_DATREA, 1, 6)
        from DTW010 (nolock)
        where 
                DTW010.D_E_L_E_T_ = ''
            and DTW010.DTW_FILORI = DTQ.DTQ_FILORI
            and DTW010.DTW_VIAGEM = DTQ.DTQ_VIAGEM
            and DTW010.DTW_ATIVID = '050'
    ) as COMPETENCIA,

    DTR.DTR_ITEM,
    DUP.DUP_CODMOT,
    DA4.DA4_MAT,
    DA4.DA4_NOME,
    DA4.DA4_FORNEC,
    DA4.DA4_LOJA,

    DTR.DTR_CODVEI,
    (select DA3010.DA3_PLACA from DA3010 where DA3010.DA3_COD = DTR.DTR_CODVEI) as PLACA_VEI,
    DTR.DTR_CODRB1,
    (select DA3010.DA3_PLACA from DA3010 where DA3010.DA3_COD = DTR.DTR_CODRB1) as PLACA_RB1,

    DTR.DTR_CODRB2,
    DTR.DTR_CODRB3,
    
    DT6.DT6_VALFRE / (select count(DTR010.DTR_CODVEI) from DTR010 where DTR010.DTR_VIAGEM = DTQ.DTQ_VIAGEM) as CTE_CM,
    DT6.DT6_VALFRE as CTE_TOTAL,
    DT6.DT6_VALIMP / (select count(DTR010.DTR_CODVEI) from DTR010 where DTR010.DTR_VIAGEM = DTQ.DTQ_VIAGEM) IMPOSTO_CM,
    DT6.DT6_VALIMP as IMPOSTO_TOTAL,
    DT6.DT6_VALTOT,
    DT6.DT6_CLIDEV,
    DT6.DT6_LOJDEV,
    SA1.A1_NOME,
    SD2.D2_DOC,
    SD2.D2_SERIE,
    SD2.D2_NFORI,
    SD2.D2_SERIORI,
    convert(date, SD2.D2_EMISSAO, 103) as D2_EMISSAO,
    SD2.D2_TIPO,
    SD2.D2_TOTAL,
    SD2.D2_VALIPI,
    SD2.D2_VALICM

from DTQ010 DTQ (nolock)
    inner join DA8010 DA8 (nolock)
        on DA8.D_E_L_E_T_ = ''
        and DA8.DA8_COD = DTQ.DTQ_ROTA
    inner join DTR010 DTR (nolock)
        on DTR.D_E_L_E_T_ = ''
        and DTR.DTR_FILORI = DTQ.DTQ_FILORI
        and DTR.DTR_VIAGEM = DTQ.DTQ_VIAGEM

        inner join DUP010 DUP (nolock)
            on DUP.D_E_L_E_T_ = ''
            and DUP.DUP_FILORI = DTR.DTR_FILORI
            and DUP.DUP_VIAGEM = DTR.DTR_VIAGEM
            and DUP.DUP_ITEDTR = DTR.DTR_ITEM
            and DUP.DUP_CODVEI = DTR.DTR_CODVEI

            inner join DA4010 DA4 (nolock)
                on DA4.DA4_COD = DUP.DUP_CODMOT

    left join DUD010 DUD (nolock)
        on DUD.D_E_L_E_T_ = ''
        and DUD.DUD_VIAGEM = DTQ.DTQ_VIAGEM

		left join DT6010 DT6 (nolock)
			on DT6.D_E_L_E_T_ = ''
			and DT6.DT6_FILDOC = DUD.DUD_FILDOC
			and DT6.DT6_DOC = DUD.DUD_DOC
			and DT6.DT6_SERIE = DUD.DUD_SERIE

            left join SD2010 SD2 (nolock)
                on SD2.D_E_L_E_T_ = ''
                and SD2.D2_NFORI = DT6.DT6_DOC
                and SD2.D2_SERIORI = DT6.DT6_SERIE
                and SD2.D2_CLIENTE = DT6.DT6_CLIDEV
                and SD2.D2_LOJA = DT6.DT6_LOJDEV
            left join SA1010 SA1 (nolock)
                on SA1.D_E_L_E_T_ = ''
                and SA1.A1_COD = DT6.DT6_CLIDEV
                and SA1.A1_LOJA = DT6.DT6_LOJDEV
where 
        DTQ.D_E_L_E_T_ = ''
    and SD2.D2_DOC in ('000001191', '000001192', '000001193', '000001194', '000001196', '000001197', '000001198', '000001202', '000001203', '000001204', '000001205', '000001206', '000001207', '000001208', '000001209', '000001219', '000000261', '000000262', '000001240', '000001241', '000001242', '000001243', '000001244', '000001245', '000001963', '000001279', '000001280', '000001281', '000001282', '000001283', '000000263', '000000264', '000001293', '000001294', '000001295', '000001296', '000001297', '000001298', '000001299', '000001300', '000001301', '000001302', '000001303', '000001304', '000001305', '000001306', '000001307', '000001308', '000001309', '000001310', '000001311', '000001312', '000000265', '000001313', '000001314', '000001315', '000001316', '000001317', '000001318', '000001319', '000001320', '000001321', '000001322', '000001323', '000001324', '000001325', '000001326', '000001327', '000001328', '000001329', '000001330', '000001331', '000001332', '000001333', '000001334', '000001335', '000001336', '000001337', '000001338', '000001339', '000001340', '000001341', '000001342', '000001343', '000001344', '000001345', '000001346', '000001347', '000001348', '000001349', '000001350', '000001351', '000001352', '000001353', '000001354', '000001355', '000001356', '000001357', '000001358', '000001359', '000001360', '000001361', '000001362', '000001363', '000001364', '000001365', '000001366', '000001367', '000001368', '000001369', '000001370', '000001371', '000001372', '000001373', '000001374', '000001375', '000001376', '000001378', '000001379', '000001380', '000001381', '000001382', '000001383', '000001384', '000001385', '000001386', '000001387', '000001388', '000001389', '000001390', '000001391', '000001392', '000001393', '000001394', '000001395', '000001396', '000001397', '000001398', '000001399', '000001400', '000001401', '000001402', '000001403', '000001404', '000001405', '000001406', '000001407', '000001408', '000001455', '000001456', '000001457', '000001458', '000001459', '000001462', '000001463', '000001464', '000001465', '000001466', '000001467', '000001468', '000001469', '000001470', '000001471', '000001472', '000001473', '000001474', '000001475', '000000266', '000001486', '000001495', '000001497', '000001499', '000001500', '000001501', '000051143', '000051144', '000001521', '000001528', '000001532', '000001533', '000001534', '000001537', '000001538', '000051238', '000001564', '000001565', '000001566', '000001567', '000001568', '000001569', '000001570', '000001571', '000001572', '000001573', '000001574', '000001575', '000001576', '000001577', '000001578', '000001579', '000051325', '000001608', '000001621', '000001622', '000001623', '000001624', '000001625', '000001626', '000001627', '000001628', '000001629', '000001630', '000001631', '000001632', '000001633', '000001634', '000001635', '000001636', '000001637', '000001638', '000001639', '000001640', '000001641', '000001642', '000001643', '000001644', '000001645', '000001646', '000001647', '000001648', '000001649', '000001650', '000001651', '000001666', '000051543', '000051546', '000000268', '000000269', '000001681', '000000270', '000000271', '000001686')